"""Source-backed practice content. See docs/sources for the dated evidence."""
TREATMENTS = [
    dict(slug='white-fillings', title='White fillings', category='Everyday dentistry', image='white-fillings', alt='Illustration of a tooth restored with a white filling', intro='A natural-looking way to restore a damaged tooth.', about='Composite fillings can restore areas affected by decay or damage. The material is selected to blend with the surrounding tooth. Your dentist will assess the tooth and discuss suitable materials before treatment.', steps=['Examine the tooth and discuss the options.', 'Prepare the area and place the chosen filling.', 'Check the bite and explain how to care for the restoration.'], question='Can an old filling be replaced?', answer='A dentist can assess the condition of an existing filling and whether replacement would be appropriate. A sound filling does not automatically need changing.', related=['root-canal','dental-hygiene']),
    dict(slug='dental-implants',title='Dental implants',category='Restoring your smile',image='dental-implants',alt='Illustration showing an implant replacing a missing tooth',intro='Explore a lasting replacement for a missing tooth.',about='An implant replaces a tooth root and can support a replacement tooth. A consultation considers your mouth, health and available bone, alongside alternatives such as a bridge or denture. Treatment involves several stages and a period of healing.',steps=['Discuss your goals, dental health and alternatives.', 'Arrange appropriate imaging and an individual treatment plan.', 'Plan placement, healing and the final restoration with your clinician.'],question='Is an implant suitable for everyone?',answer='Suitability depends on an individual assessment. Ask about the full treatment plan, possible additional procedures, risks, maintenance and total cost.',related=['imaging','wisdom-teeth']),
    dict(slug='invisible-braces',title='Invisible braces',category='Smile confidence',image='invisible-braces',alt='Clear removable dental aligner',intro='A discreet approach to straighter teeth.',about='Clear aligners can move teeth gradually through a planned sequence of removable trays. The right approach depends on your bite, oral health and the movement required. Ask the team which aligner options they currently provide.',steps=['Assess your teeth, bite and goals.', 'Discuss the proposed plan and daily wear requirements.', 'Review progress and plan retention after treatment.'],question='How long will treatment take?',answer='Your clinician can estimate the duration after assessing your teeth. Complexity and wearing the aligners as instructed affect progress.',related=['smile-makeovers','dental-hygiene']),
    dict(slug='root-canal',title='Root canal treatment',category='Everyday dentistry',image='root-canal',alt='Illustration of treatment inside the root of a tooth',intro='Treatment focused on preserving your natural tooth.',about='Root canal treatment removes infected tissue from inside a tooth. The canals are cleaned and filled, and the tooth is restored. Your dentist will explain whether the tooth can be treated and whether a crown may be needed afterwards.',steps=['Assess the tooth and take imaging if needed.', 'Clean and fill the root canals under local anaesthetic.', 'Restore the tooth and arrange any necessary follow-up.'],question='Will I need more than one appointment?',answer='Root canal treatment often takes more than one visit. Your dentist will explain the expected stages and how the tooth will be protected between appointments.',related=['white-fillings','dental-implants']),
    dict(slug='dental-hygiene',title='Dental hygiene',category='Everyday dentistry',image='dental-hygiene',alt='Dental hygiene treatment around the teeth and gums',intro='Support for healthier teeth and gums, every day.',about='Hygiene appointments focus on gum health, professional cleaning and practical advice for caring for your mouth at home. The team can recommend an appointment interval based on your needs, rather than a fixed schedule for everyone.',steps=['Discuss your home routine and assess gum health.', 'Remove deposits where clinically appropriate.', 'Agree on home care and a suitable review interval.'],question='How often should I book?',answer='Your dentist or dental therapist can recommend how frequently to attend after assessing your oral health and risk factors.',related=['white-fillings','teeth-whitening']),
    dict(slug='wisdom-teeth',title='Wisdom-tooth care',category='Restoring your smile',image='wisdom-teeth',alt='Dental illustration showing the position of a wisdom tooth',intro='Clear guidance when wisdom teeth cause concern.',about='Pain or repeated problems around a wisdom tooth may need assessment. The team can discuss monitoring, treatment or removal where appropriate. Imaging may be needed to understand the tooth’s position and nearby structures.',steps=['Discuss your symptoms and examine the area.', 'Review imaging and explain suitable options.', 'If treatment is needed, plan it with clear aftercare advice.'],question='Do all wisdom teeth need to be removed?',answer='No. A clinician will assess whether a wisdom tooth is causing problems and whether treatment is justified.',related=['sedation','imaging']),
    dict(slug='sedation',title='Conscious sedation',category='Comfort & wellbeing',image='sedation',alt='Patient receiving care in a dental chair',intro='Talk to us about support for dental anxiety.',about='Conscious sedation may help some people feel more relaxed during dental treatment. It is different from a general anaesthetic. The team will review your medical history, explain suitable options and provide specific preparation and recovery instructions.',steps=['Tell the team about your concerns and medical history.', 'Discuss suitability, risks and the proposed sedation method.', 'Follow the personalised preparation, escort and aftercare instructions.'],question='Will I be asleep?',answer='With conscious sedation you remain conscious. Ask your clinician what to expect and what support you will need on the day.',related=['wisdom-teeth','stress-therapy']),
    dict(slug='smile-makeovers',title='Smile makeovers',category='Smile confidence',image='smile-makeovers',alt='Illustration of dental veneers on front teeth',intro='A considered plan, shaped around your smile.',about='A smile consultation brings your priorities and oral health together. Depending on your needs, a plan may involve whitening, alignment or restorative treatment. Your dentist will explain alternatives, maintenance and the implications of each option.',steps=['Discuss what you would like to change.', 'Assess your oral health and compare suitable options.', 'Agree a staged plan and written estimate before treatment.'],question='Do I have to choose veneers?',answer='No. A consultation should explore suitable alternatives. Ask which options preserve tooth structure and what long-term maintenance they need.',related=['invisible-braces','teeth-whitening']),
    dict(slug='teeth-whitening',title='Teeth whitening',category='Smile confidence',image='smile-makeovers',alt='Dental illustration showing front teeth',intro='Professional advice for a brighter smile.',about='Wilton Dental lists Boutique and 360 whitening options. A dental assessment is the first step: whitening is not suitable for everyone and does not change the colour of fillings, crowns or veneers. Ask the team about current products and fees.',steps=['Check your oral health and suitability.', 'Discuss the expected result and possible sensitivity.', 'Follow your dental professional’s instructions and review the result.'],question='Can I whiten crowns or fillings?',answer='Whitening changes the colour of natural teeth, not existing restorations. Your dentist can explain how this affects the result you are hoping for.',related=['dental-hygiene','smile-makeovers']),
    dict(slug='facial-aesthetics',title='Facial aesthetics',category='Skin & wellbeing',image='facial-aesthetics',alt='Image used by the practice to illustrate facial aesthetics',intro='An individual conversation about your aesthetic goals.',about='The practice lists facial aesthetics among its services. Contact the team to confirm the treatments currently available, who provides them and where the appointment will take place. A consultation should cover suitability, alternatives, risks and aftercare.',steps=['Explain your goals and relevant medical history.', 'Confirm the practitioner, treatment and suitability.', 'Review costs, consent and aftercare before deciding.'],question='How do I find out what is available?',answer='Speak directly with the practice. Its existing website also links to an external aesthetics provider; the team can confirm the current service arrangements.',related=['microdermabrasion','microneedling']),
    dict(slug='stress-therapy',title='Stress therapy',category='Comfort & wellbeing',image='stress-therapy',alt='Practice illustration for stress and wellbeing support',intro='Start a conversation about feeling more at ease.',about='Stress therapy is listed on the practice website. Ask the team what support is currently offered, the practitioner’s qualifications and how an appointment is arranged. If your concern relates to visiting the dentist, tell the team when you contact them.',steps=['Describe the support you are looking for.', 'Confirm the service, practitioner and appointment format.', 'Discuss next steps and any appropriate onward support.'],question='Is this the same as dental sedation?',answer='No. These are separate services. If dental treatment makes you anxious, the team can discuss the support and treatment options relevant to your visit.',related=['sedation','dental-hygiene']),
    dict(slug='microdermabrasion',title='Microdermabrasion',category='Skin & wellbeing',image='facial-aesthetics',alt='Practice image illustrating skin care',intro='A consultation-led approach to skin resurfacing.',about='The practice describes microdermabrasion as an exfoliating skin treatment. Discuss your skin concerns, medical history, suitability and expected recovery with the practitioner. Results and the number of appointments vary.',steps=['Review your skin concerns and suitability.', 'Discuss the procedure, limitations and possible side effects.', 'Agree on aftercare and any follow-up appointments.'],question='How is it different from microneedling?',answer='Microdermabrasion focuses on surface exfoliation. Microneedling is a different procedure. Ask the practitioner to explain which, if either, is appropriate for your skin.',related=['microneedling','facial-aesthetics']),
    dict(slug='microneedling',title='Microneedling',category='Skin & wellbeing',image='facial-aesthetics',alt='Practice image illustrating skin care consultations',intro='Understand your skin-treatment options before deciding.',about='Wilton Dental’s skin-care page lists microneedling alongside microdermabrasion. A consultation should address your goals, suitability, likely recovery and possible risks. Ask who will provide treatment and what aftercare is included.',steps=['Discuss your skin and medical history.', 'Review benefits, limitations, risks and recovery.', 'Confirm the treatment plan and aftercare with your practitioner.'],question='Can I decide at the consultation?',answer='Use the consultation to ask questions and consider the information. You should understand the procedure and its costs before agreeing to treatment.',related=['microdermabrasion','facial-aesthetics']),
]
